import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and current year `now`.

    Only years are compared, so the result is `now - born`. The current
    year is passed in; the clock is never read.

    Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError("now is earlier than born")
    return now - born


def test_age_basic() -> None:
    assert age_at(1990, 2020) == 30
    assert age_at(2000, 2001) == 1


def test_age_same_year_is_zero() -> None:
    assert age_at(2024, 2024) == 0


def test_age_large_span() -> None:
    assert age_at(1, 2024) == 2023


def test_age_negative_years() -> None:
    assert age_at(-100, 50) == 150


def test_age_now_before_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)


def test_age_returns_int() -> None:
    assert isinstance(age_at(1980, 2000), int)
